        insightWhy: {
            salesDown: "This compares your sales against the same number of days immediately before, so it is like-for-like. A drop is usually a few lines that stopped moving, not every line falling a little.",
            salesUp: "Measured against the same number of days immediately before. Growth this size normally comes from a handful of items, not from everything at once.",
            noCostPrice: "Profit is selling price minus cost price. Where the cost is blank the app has to treat it as zero, which makes that sale look like pure profit and pulls every margin on this page upward.",
            marginThin: "Margin is what is left after the cost of the goods, before rent and salaries. A thin one means either you are buying too dear or selling too cheap — the number alone cannot tell you which.",
            expensesEatMargin: "Rent, salaries, electricity and the rest come out of margin, not out of sales. A healthy-looking margin can still leave nothing once they are paid.",
            udhaarGrowing: "This compares udhaar given in the period against udhaar collected in it. When more goes out than comes back, your working capital is quietly moving onto other people's shelves.",
            agingRisk: "The older a debt gets the less often it is paid — this is true of every shop everywhere. Past sixty days the odds fall sharply, which is why this is separated from the rest of your khata.",
            outOfStockSelling: "These are items that proved they sell and then hit zero. Unlike slow stock, an empty shelf costs you nothing to look at and everything in sales you never made.",
            deadStock: "Money spent on goods is money you cannot spend on anything else. Stock that has not moved in months is your own cash sitting still, and it is usually the oldest purchases.",
            atRiskCustomers: "A regular who stops coming rarely announces it. Most have simply started buying somewhere closer or cheaper, and most come back for one phone call.",
            repeatStrong: "Repeat customers cost nothing to acquire and spend more per visit than a stranger. A high share here is the single strongest sign of a healthy shop.",
            repeatWeak: "Footfall without return means you are paying to attract someone once and then losing them. It is the most expensive way to run a shop.",
            targetBehind: "The per-day figure is what is left, divided by the days remaining — not an average of what you have done so far.",
            targetHit: "You crossed the number you set. A target that is met early was set below what the shop can actually do.",
            peakHour: "Bills cluster far more than most shopkeepers expect. Knowing the hour tells you when a second pair of hands actually pays for itself.",
            weekdaySpread: "Buying and staffing evenly across the week is the default, and it is almost never right. The gap between your best and worst day is usually large.",
            returnsHigh: "Returns at this level are rarely bad luck. They point at a quality problem in specific lines, or a price the customer regretted after leaving.",
            steady: "No sharp movement in either direction, and nothing on the page crossed a threshold worth flagging."
        },
        insightDo: {
            salesDown: "Open your item-wise report for both periods and compare the top twenty. The lines that fell will be obvious, and usually two or three explain most of the drop.",
            salesUp: "Find which items grew and make sure they do not run out — an item that sells out during its own good run is the most expensive stockout there is.",
            noCostPrice: "Fill the cost price on your highest-selling items first. Twenty items usually covers most of your sales, and every figure on this page becomes real.",
            marginThin: "Take your ten best-selling items and check each one's buying rate against what you charge. Fix the worst two or three rather than repricing everything.",
            expensesEatMargin: "Open your expense list for the period and sort by amount. The answer is usually one or two lines, not many small ones.",
            udhaarGrowing: "Start with the oldest balances, not the biggest. Send this week's reminders from the khata screen before giving any more credit.",
            agingRisk: "Call these customers before the newer ones. Offer a part payment if the full amount is the reason nobody is paying — half of an old balance beats all of nothing.",
            outOfStockSelling: "Raise a purchase order for these today. They already proved there is demand, so this is the safest restock in your shop.",
            deadStock: "Pick the three with the most money in them and decide one thing for each — an offer, a price cut, or back to the wholesaler. Doing nothing is also a decision, just a slower one.",
            atRiskCustomers: "Call five of them this week. Not a message — a call, and mention something they used to buy.",
            repeatStrong: "Protect it. Make sure what they come back for is never out of stock, and consider a small loyalty benefit for the top few.",
            repeatWeak: "Take the phone number at the counter and give a reason to return — a points card or a small discount on the next visit does most of the work.",
            targetBehind: "Either lift the daily number or lower the target. A target nobody can reach stops being used within a month.",
            targetHit: "Set next month's from what you actually did, not from what you hoped. Somewhere above this month is the right place to start.",
            peakHour: "Put your best biller on the counter for that hour, and keep the fastest-moving items within arm's reach of it.",
            weekdaySpread: "Take delivery before your best day, not after it, and keep the shop lighter on your worst.",
            returnsHigh: "Look at which items are coming back. If it is one line, take it up with the wholesaler; if it is spread out, the problem is usually price.",
            steady: "Nothing needs fixing today. This is a good week to fill in cost prices or clear old khata — the jobs that never feel urgent."
        },
